func _draw() -> void :
				if not Levels.is_current_level_hideout():
								return
				draw_grid_cover()

func draw_grid_cover() -> void :
				var cam_pos = GameState.get_global("player").global_position
				var range_v := Vector2(1280.0, 800.0)
				var start_x = floor((cam_pos.x - range_v.x - 32.0) / 32.0) * 32.0
				var start_y = floor((cam_pos.y - range_v.y - 32.0) / 32.0) * 32.0
				var end_x = cam_pos.x + range_v.x + 32.0
				var end_y = cam_pos.y + range_v.y + 32.0
				var minor_color := Color(0.160784, 0.211765, 0.258824, 0.10)
				var major_color := Color(0.25098, 0.32549, 0.396078, 0.20)
				var x = start_x
				while x <= end_x:
								var is_major_x = int(x / 32.0) % 4 == 0
								var line_color_x = major_color if is_major_x else minor_color
								draw_line(Vector2(x, start_y), Vector2(x, end_y), line_color_x, 2.0, true)
								x += 32.0
				var y = start_y
				while y <= end_y:
								var is_major_y = int(y / 32.0) % 4 == 0
								var line_color_y = major_color if is_major_y else minor_color
								draw_line(Vector2(start_x, y), Vector2(end_x, y), line_color_y, 2.0, true)
								y += 32.0
